// Webhook integrity check (opt-in via WEBHOOK_INTEGRITY_CHECK_ENABLED=1).
// Telegram Trigger handles HMAC via its secretToken option (set on the
// trigger node itself). This Code node is the second defense layer:
// reject malformed payloads that lack the fields downstream nodes expect.
//
// To enable: set the n8n env var WEBHOOK_INTEGRITY_CHECK_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.

const enabled = $env.WEBHOOK_INTEGRITY_CHECK_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const message = item?.message ?? item;

if (!message || typeof message !== 'object') {
  throw new Error('Webhook integrity check failed: no message object');
}
if (typeof message.from?.id !== 'number' && typeof message.from?.id !== 'string') {
  throw new Error('Webhook integrity check failed: missing message.from.id');
}
if (typeof message.chat?.id !== 'number' && typeof message.chat?.id !== 'string') {
  throw new Error('Webhook integrity check failed: missing message.chat.id');
}
if (typeof message.text !== 'string' && typeof message.caption !== 'string') {
  throw new Error('Webhook integrity check failed: no text or caption');
}

return [{ json: item }];

// Rate limit (opt-in via RATE_LIMIT_ENABLED=1).
// Per-chat-id 60 requests in a 5-minute window. Tracked in workflow
// static data (per-instance). For clustered n8n deployments or higher
// throughput, use Nginx limit_req_zone or Cloudflare WAF instead.
//
// To enable: set the n8n env var RATE_LIMIT_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.
//
// Concurrency note: $getWorkflowStaticData is not atomic. Under heavy
// burst load the count can over-shoot the limit by a few percent. For
// hard limits use a reverse proxy or Redis INCR + EXPIRE.

const enabled = $env.RATE_LIMIT_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const message = item?.message ?? item;
const chatId = message?.chat?.id ?? message?.from?.id ?? 'unknown';
const bucketKey = `chat:${chatId}`;

const data = $getWorkflowStaticData('global');
const buckets = data.rateBuckets ?? {};
const now = Date.now();
const WINDOW_MS = 5 * 60 * 1000;
const LIMIT = 60;
const MAX_BUCKETS = 5000;

const bucket = buckets[bucketKey] ?? { count: 0, windowStart: now };
if (now - bucket.windowStart > WINDOW_MS) {
  bucket.count = 0;
  bucket.windowStart = now;
}
bucket.count++;
buckets[bucketKey] = bucket;

// Bound the map: evict expired entries when full
if (Object.keys(buckets).length > MAX_BUCKETS) {
  const cutoff = now - WINDOW_MS;
  for (const k of Object.keys(buckets)) {
    if (buckets[k].windowStart < cutoff) delete buckets[k];
  }
}
data.rateBuckets = buckets;

if (bucket.count > LIMIT) {
  throw new Error(`Rate limit exceeded for ${bucketKey}: ${bucket.count} requests in 5 min window`);
}

return [{ json: item }];

// Idempotency check (opt-in via IDEMPOTENCY_ENABLED=1).
// Telegram retries on 5xx. Without dedup, the workflow fires twice and
// writes Memory twice. This node holds a 5-minute in-memory window of
// seen update_ids and short-circuits duplicates.
//
// To enable: set the n8n env var IDEMPOTENCY_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.
//
// Concurrency note: $getWorkflowStaticData is not atomic and not cluster-
// aware. Two simultaneous fires of the same update_id may both pass.
// For production scale, swap the staticData block for Redis SET NX EX 300.

const enabled = $env.IDEMPOTENCY_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const message = item?.message ?? item;
const updateId = item?.update_id ?? message?.update_id;
const messageId = message?.message_id;
const idempotencyKey = updateId ? `tg-update:${updateId}` : (messageId ? `tg-msg:${messageId}` : null);

if (!idempotencyKey) {
  // No dedup key available, pass through
  return [{ json: item }];
}

const data = $getWorkflowStaticData('global');
const seen = data.seenKeys ?? {};
const now = Date.now();
const WINDOW_MS = 5 * 60 * 1000;

// Purge expired entries
for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}

if (seen[idempotencyKey]) {
  // Duplicate detected. Emit a sentinel item that the
  // 'Skip If Duplicate' IF node routes to 'Respond Duplicate'
  // (200 OK + { deduped: true }). Without that 200 the source
  // provider would hold the HTTP connection until n8n's webhook
  // timeout (default 30s) and mark delivery failed.
  return [{ json: { skipped: true, reason: 'duplicate', dedupKey: String(idempotencyKey) } }];
}
seen[idempotencyKey] = now;
data.seenKeys = seen;

return [{ json: item }];

// Extract lead identity + form fields from the incoming webhook payload.
// Form context: lead fills out a form on your landing page with email, name,
// company, and a free-text message about their problem. We extract email as
// the primary key (more stable than name) and pass the rest forward as
// observations to be stored on the lead entity.

const body = $input.first().json;

const email = (body?.email ?? body?.email_address ?? '').trim().toLowerCase();
const name = (body?.name ?? body?.full_name ?? '').trim();
const company = (body?.company ?? body?.organization ?? '').trim();
const phone = (body?.phone ?? body?.tel ?? '').trim();
const message = (body?.message ?? body?.notes ?? body?.question ?? '').trim();
const source = body?.source ?? body?.utm_source ?? body?.referrer ?? 'unknown';

if (!email || !email.includes('@')) {
  throw new Error('Missing or invalid email in form payload (required field: email).');
}

if (!message) {
  throw new Error('Missing message text in form payload (required field: message).');
}

return [{
  json: {
    customerKey: email,            // reuse downstream "customerKey" naming for entity-lookup parity with T02
    customerLabel: name || company || email,
    email,
    name,
    company,
    phone,
    messageText: message,
    source,
    receivedAt: new Date().toISOString(),
  },
}];

// Build a system + user prompt for the LLM that performs BANT+I classification.
// BANT = Budget, Authority, Need, Timeline. The "I" extension is Intent
// (buying-signal strength: 1-5).
//
// We ask the LLM to return STRICT JSON with five integer scores 1-5 and a
// brief justification per dimension. Downstream Pipedrive node uses the
// total score + bucketed-state to decide which Pipedrive Pipeline to assign.

const customerKey = $('Extract Lead').item.json.customerKey;
const customerLabel = $('Extract Lead').item.json.customerLabel;
const messageText = $('Extract Lead').item.json.messageText;
const company = $('Extract Lead').item.json.company;

const dossierRaw = $input.first().json;
const dossier = dossierRaw?.data ?? dossierRaw;
const observations = dossier?.observations ?? [];
const priorBant = observations
  .slice(-5)
  .map(o => `- ${o?.created_at?.slice(0, 10) ?? '?'}: ${(o?.content ?? '').slice(0, 200)}`)
  .join('\n');

const systemPrompt = `You are a B2B sales-qualification assistant. You evaluate inbound leads on the BANT+I framework and return STRICT JSON only.

BANT+I dimensions (each 1-5):
- B Budget: 1=no budget signal, 5=explicit budget mentioned
- A Authority: 1=junior IC, 5=decision-maker (C-level, founder, head-of)
- N Need: 1=vague exploration, 5=specific painful problem with impact mentioned
- T Timeline: 1=no urgency, 5=signed RFP or "this quarter"
- I Intent: 1=research-mode browsing, 5=buying-signal explicit ("looking for vendors")

Return ONLY a JSON object of this exact shape, no markdown, no preamble:
{
  "scores": { "B": 1-5, "A": 1-5, "N": 1-5, "T": 1-5, "I": 1-5 },
  "total": <sum of scores>,
  "qualifiedAs": "hot" | "warm" | "cold",
  "summary": "one sentence in English with the why behind the bucketing",
  "nextAction": "one sentence with what sales rep should do next"
}

Bucketing rule: total >= 20 = hot, 15-19 = warm, < 15 = cold.

Lead label: ${customerLabel}
Company: ${company || '(not provided)'}
Lead message: ${messageText}

Prior BANT observations on this lead (most-recent last):
${priorBant || '(no prior interactions on file, this is a first-time lead)'}`;

return [{
  json: {
    systemPrompt,
    messageText,
    customerKey,
    customerLabel,
  },
}];

// LLM Fallback Reply: fires when OpenAI/Anthropic Reply errors,
// or when Route by Provider receives an unknown provider value.
//
// Two arrival paths:
//   1. LLM error - input has $json.error
//   2. Router fallback - input has the original prompt object including
//      systemPrompt with the full BANT-context (prior lead history).
//      We must NOT JSON.stringify the whole input.

const errorRaw = $input.first().json;
const provider = $('Set Provider').item.json.provider ?? 'unknown';

const isLlmError = !!(errorRaw?.error || errorRaw?.message);
let errorMessage;
if (isLlmError) {
  errorMessage = errorRaw?.error?.message
    ?? errorRaw?.error?.name
    ?? errorRaw?.message
    ?? 'Unknown LLM error';
} else {
  errorMessage = `Unknown provider value: ${provider}. Set "provider" to "openai" or "anthropic" in the Set Provider node.`;
}

const customerKey = $('Extract Lead').item.json.customerKey;
const customerLabel = $('Extract Lead').item.json.customerLabel;
const messageText = $('Extract Lead').item.json.messageText;

return [{
  json: {
    scores: { B: 1, A: 1, N: 1, T: 1, I: 1 },
    total: 5,
    qualifiedAs: 'cold',
    summary: 'Qualifier unavailable, lead defaulted to cold for human review.',
    nextAction: 'Manual review required: BANT classifier failed.',
    provider,
    isFallback: true,
    isRouterFallback: !isLlmError,
    errorMessage: String(errorMessage),
    customerKey,
    customerLabel,
    messageText,
    replyText: 'Qualifier unavailable, lead defaulted to cold.',
  },
}];

// Parse the strict-JSON BANT+I response from either OpenAI or Anthropic
// and lift the structured fields up so downstream nodes can pivot on them.
//
// OpenAI shape: $json.choices[0].message.content (string with JSON inside)
// Anthropic shape: $json.content[0].text (string with JSON inside)
//
// LLMs sometimes wrap JSON in fenced code blocks despite instructions. We
// strip ``` and ```json fences before parsing, then fall back to raw.

const raw = $input.first().json;
let text = '';

if (raw?.choices?.[0]?.message?.content) {
  text = raw.choices[0].message.content;
} else if (Array.isArray(raw?.content) && raw.content[0]?.text) {
  text = raw.content[0].text;
} else if (raw?.message?.content) {
  text = raw.message.content;
} else if (raw?.text) {
  text = raw.text;
}

text = String(text).trim();
text = text.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  // LLM returned non-JSON: degrade gracefully, qualify as cold for safety
  parsed = {
    scores: { B: 1, A: 1, N: 1, T: 1, I: 1 },
    total: 5,
    qualifiedAs: 'cold',
    summary: 'LLM did not return valid JSON, lead defaulted to cold for safety. Raw output: ' + text.slice(0, 120),
    nextAction: 'Manual review required: classifier output was unparseable.',
  };
}

const total = Number(parsed?.total ?? 0);
const qualifiedAs = parsed?.qualifiedAs ?? (total >= 20 ? 'hot' : total >= 15 ? 'warm' : 'cold');

return [{
  json: {
    scores: parsed?.scores ?? {},
    total,
    qualifiedAs,
    summary: parsed?.summary ?? '',
    nextAction: parsed?.nextAction ?? '',
    provider: $('Set Provider').item.json.provider,
    replyText: parsed?.summary ?? 'Lead qualified.',
  },
}];
